from slug import slugify


def test_basic():
    assert slugify('Hello World') == 'hello-world'


def test_collision_suffix():
    assert slugify('Hello World') == 'hello-world'
    assert slugify('Hello  World') == 'hello-world-2'
    assert slugify('hello world') == 'hello-world-3'


def test_distinct_titles_unaffected():
    assert slugify('Other Thing') == 'other-thing'
